@startuml

enum SubscriptionType {
  Monthly
  Annual
}

enum ServiceType {
  WeightRoom
  SwimmingPool
  ClimbingWall
  Sauna
  TurkishBath
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
  + subscriptionType : SubscriptionType
}

class Subscription {
  + baseFee : float
}

class AdditionalService {
  + price : float
}

class WorkoutPlan {
  + exercises : string[]
  + repetitions : int
  + frequency : int
}

class MedicalCheck {
  + date : date
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
  + name : string
}

class Diet {
  + description : string
}

class Gym {
  + totalIncomeMonthly : float
  + totalIncomeYearly : float
}

Customer "1" -- "*" AdditionalService : requests
Customer "1" -- "0..1" WorkoutPlan : associated with
Customer "1" -- "0..*" MedicalCheck : undergoes
Customer "1" -- "0..1" Diet : follows
MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "*" Diet : defines
Gym "1" -- "*" Customer : manages
Gym "1" -- "*" Subscription : offers
Gym "1" -- "*" AdditionalService : offers

@enduml

